    SELECT
        'PCOM'||
        LPAD(NVL(TO_NUMBER(SUBSTR(MAX(COMMENT_NO), LENGTH('PCOM' ) + 1)), 0) + 1, 6, '0')
    FROM PRJ_BBS_COMMENT

