	COMMENT_NO
	, PRJ_POST_NO
	, PRJ_NO
	, USER_ID
	, COMMENT_CONTENT
	, CREATE_DATE
) VALUES (
	#{commentNo}
	, #{prjPostNo}
	, #{prjNo}
	, #{userId}
	, #{commentContent}
	, SYSDATE
)

